func PathEscape(pth string) string {
	// The path may contain a hash sign, which url.Parse treats as the start of
	// a fragment. Escape it before parsing to keep it part of the path.
	pth = strings.ReplaceAll(pth, "#", "%23")
	u, err := url.Parse(pth)
	if err != nil {
		panic(err)
	}
	return u.EscapedPath()
}

